/* De piramide: kenmerken, uitslag, inhoud en oppervlakte. */
var WIS_PIRAMIDE = [
{"v":"Welke vorm hebben de zijvlakken van een piramide altijd?","o":["driehoek","rechthoek","vierkant","cirkel"],"g":0,"u":"Elk zijvlak loopt van een zijde van het grondvlak naar de ene top. Zo krijg je altijd een driehoek.","t":"piramide","n":1,"w":{"rechthoek":"Rechthoeken als zijvlakken horen bij een prisma of een balk, niet bij een piramide.","vierkant":"Het grondvlak kan een vierkant zijn, maar de zijvlakken lopen spits toe naar de top.","cirkel":"Een cirkel is het grondvlak van een kegel; een zijvlak van een piramide is nooit rond."}},
{"v":"Een piramide heeft een vierkant als grondvlak. Hoeveel vlakken heeft hij in totaal?","o":["4","5","6","8"],"g":1,"u":"Het grondvlak is 1 vlak en aan elke zijde van het vierkant zit een driehoek: 1 + 4 = 5 vlakken.","t":"piramide","n":1,"w":{"4":"Je telde alleen de vier driehoeken en vergat het grondvlak.","6":"Zes vlakken heeft een kubus; een piramide heeft boven geen vlak maar een top.","8":"Je telde de ribben in plaats van de vlakken."}},
{"v":"Een piramide heeft een vierkant als grondvlak. Hoeveel ribben heeft hij?","o":["5","4","8","12"],"g":2,"u":"Het vierkant heeft 4 ribben en vanaf elk hoekpunt loopt er 1 ribbe naar de top: 4 + 4 = 8 ribben.","t":"piramide","n":1,"w":{"4":"Je telde alleen de ribben van het grondvlak en vergat de vier ribben naar de top.","5":"Je telde de hoekpunten in plaats van de ribben.","12":"Twaalf ribben heeft een kubus, niet een piramide."}},
{"v":"Een piramide heeft een driehoek als grondvlak. Hoeveel vlakken heeft hij in totaal?","o":["3","6","5","4"],"g":3,"u":"Het grondvlak is 1 vlak en aan elke zijde van de driehoek zit een zijvlak: 1 + 3 = 4 vlakken.","t":"piramide","n":1,"w":{"3":"Je telde alleen de drie zijvlakken en vergat het grondvlak.","5":"Vijf vlakken hoort bij een piramide met een vierkant als grondvlak.","6":"Je telde de ribben in plaats van de vlakken."}},
{"v":"Een piramide heeft een vijfhoek als grondvlak. Hoeveel hoekpunten heeft hij?","o":["6","5","10","7"],"g":0,"u":"De vijfhoek heeft 5 hoekpunten en de top komt erbij: 5 + 1 = 6 hoekpunten.","t":"piramide","n":2,"w":{"5":"Je telde alleen de hoekpunten van het grondvlak en vergat de top.","7":"Zeven hoekpunten hoort bij een zeshoek als grondvlak; een vijfhoek heeft maar 5 hoeken.","10":"Je telde de ribben (2 × 5) in plaats van de hoekpunten."}},
{"v":"Een piramide heeft een zeshoek als grondvlak. Hoeveel ribben heeft hij?","o":["7","12","6","18"],"g":1,"u":"De zeshoek heeft 6 ribben en vanaf elk hoekpunt loopt er 1 ribbe naar de top: 6 + 6 = 12 ribben.","t":"piramide","n":2,"w":{"6":"Je telde alleen de ribben van het grondvlak en vergat de ribben naar de top.","7":"Je telde de hoekpunten of de vlakken (6 + 1) in plaats van de ribben.","18":"Achttien ribben heeft een prisma met een zeshoek, want dat heeft twee grondvlakken."}},
{"v":"Welk voorwerp heeft de vorm van een piramide?","o":["een dobbelsteen van een bordspel","een blik soep uit de supermarkt","het puntdak van een vierkante toren","een schoenendoos met een deksel"],"g":2,"u":"Zo'n puntdak heeft een vierkant als grondvlak en vier driehoeken die bij één top samenkomen. Dat is een piramide.","t":"piramide","n":1,"w":{"een dobbelsteen van een bordspel":"Een dobbelsteen is een kubus: zes vierkanten en geen top.","een blik soep uit de supermarkt":"Een blik is een cilinder: twee cirkels en een ronde wand.","een schoenendoos met een deksel":"Een schoenendoos is een balk: alleen rechthoeken en geen top."}},
{"v":"Wat is het verschil tussen een piramide en een kegel?","o":["een kegel heeft geen top bovenaan","een kegel heeft twee grondvlakken","een piramide heeft geen grondvlak","een kegel heeft een rond grondvlak"],"g":3,"u":"Allebei lopen ze uit in een top. Bij een kegel is het grondvlak een cirkel, bij een piramide een veelhoek met rechte zijden.","t":"piramide","n":2,"w":{"een kegel heeft geen top bovenaan":"Een kegel loopt net als een piramide uit in een top.","een kegel heeft twee grondvlakken":"Twee grondvlakken horen bij een cilinder of een prisma, niet bij een kegel.","een piramide heeft geen grondvlak":"Een piramide staat op een grondvlak, bijvoorbeeld een vierkant of een driehoek."}},
{"v":"Wat is het verschil tussen een piramide en een prisma?","o":["een piramide loopt uit in een top","een prisma heeft altijd een top","een prisma heeft geen ribben","een piramide heeft twee grondvlakken"],"g":0,"u":"Een prisma heeft onder en boven hetzelfde vlak en is overal even dik. Een piramide heeft één grondvlak en loopt spits toe naar de top.","t":"piramide","n":2,"w":{"een prisma heeft altijd een top":"Je verwisselde de twee: de piramide heeft een top, het prisma een bovenvlak.","een prisma heeft geen ribben":"Een prisma heeft juist veel ribben: rond beide grondvlakken en ertussen.","een piramide heeft twee grondvlakken":"Twee gelijke grondvlakken horen bij het prisma; een piramide heeft er één."}},
{"v":"Wat bedoel je met de hoogte van een piramide?","o":["de lengte van één opstaande ribbe","loodrecht van de top naar het grondvlak","de hoogte van een driehoekig zijvlak","de langste zijde van het grondvlak"],"g":1,"u":"De hoogte meet je recht naar beneden: loodrecht van de top op het grondvlak. Een ribbe en een zijvlak staan schuin en zijn dus langer.","t":"piramide","n":3,"w":{"de lengte van één opstaande ribbe":"Een opstaande ribbe loopt schuin naar de top en is langer dan de hoogte.","de hoogte van een driehoekig zijvlak":"Dat is de schuine hoogte; het zijvlak helt, dus die is langer dan de hoogte van de piramide.","de langste zijde van het grondvlak":"Een zijde van het grondvlak ligt plat en zegt niets over hoe hoog de top zit."}},
{"v":"Een piramide heeft 7 vlakken. Hoeveel ribben heeft hij?","o":["14","7","12","6"],"g":2,"u":"Eén van de 7 vlakken is het grondvlak, dus er zijn 6 zijvlakken en het grondvlak is een zeshoek. Het aantal ribben is 2 × 6 = 12.","t":"piramide","n":4,"w":{"6":"Zes is het aantal hoeken van het grondvlak; elk hoekpunt heeft ook nog een ribbe naar de top.","7":"Zeven is het aantal hoekpunten (6 + 1), niet het aantal ribben.","14":"Je deed 2 × 7, maar je moet eerst het grondvlak eraf halen: het grondvlak heeft 6 hoeken."}},
{"v":"Je vouwt de bouwplaat van een piramide met een vierkant grondvlak open. Hoeveel driehoeken zie je?","o":["3","5","8","4"],"g":3,"u":"Aan elke zijde van het vierkant zit één driehoek. Een vierkant heeft 4 zijden, dus 4 driehoeken.","t":"piramide","n":1,"w":{"3":"Drie driehoeken hoort bij een piramide met een driehoek als grondvlak.","5":"Je telde het grondvlak mee, maar dat is een vierkant en geen driehoek.","8":"Je telde de ribben van de piramide in plaats van de driehoeken."}},
{"v":"Uit welke vlakken bestaat de uitslag van een piramide met een vierkant grondvlak?","o":["een vierkant en vier driehoeken","zes even grote vierkanten","twee vierkanten en vier rechthoeken","een cirkel en een driehoek"],"g":0,"u":"De uitslag bestaat uit het grondvlak (een vierkant) met aan elke zijde een zijvlak (een driehoek): 1 vierkant en 4 driehoeken.","t":"piramide","n":1,"w":{"zes even grote vierkanten":"Dat is de uitslag van een kubus.","twee vierkanten en vier rechthoeken":"Dat is de uitslag van een balk met een vierkant grondvlak.","een cirkel en een driehoek":"Een cirkel hoort bij een kegel; een piramide heeft alleen vlakken met rechte zijden."}},
{"v":"Je kijkt recht van boven op een piramide met een vierkant grondvlak. Wat zie je?","o":["een driehoek zonder lijnen","een vierkant met diagonalen","een cirkel met een stip","een vierkant zonder lijnen"],"g":1,"u":"Van boven zie je de omtrek van het grondvlak: een vierkant. De vier ribben naar de top zie je als de twee diagonalen.","t":"piramide","n":2,"w":{"een driehoek zonder lijnen":"Een driehoek zie je als je van opzij kijkt, niet van boven.","een cirkel met een stip":"Dat is het bovenaanzicht van een kegel.","een vierkant zonder lijnen":"Zo ziet een kubus er van boven uit; bij een piramide zie je ook de ribben naar de top."}},
{"v":"Je kijkt recht van opzij tegen een piramide met een vierkant grondvlak. Welke vorm zie je?","o":["een vierkant","een cirkel","een driehoek","een trapezium"],"g":2,"u":"Van opzij zie je onderaan de zijde van het grondvlak en twee schuine lijnen die samenkomen in de top: een driehoek.","t":"piramide","n":1,"w":{"een vierkant":"Een vierkant zie je bij een kubus; een piramide loopt naar boven spits toe.","een cirkel":"Een cirkel zie je als je van boven op een kegel kijkt.","een trapezium":"Een trapezium zie je alleen als de punt eraf is; deze piramide heeft een top."}},
{"v":"De uitslag van een piramide heeft 6 driehoeken. Welke vorm heeft het grondvlak?","o":["vijfhoek","driehoek","zevenhoek","zeshoek"],"g":3,"u":"Aan elke zijde van het grondvlak zit één driehoek. Zes driehoeken betekent zes zijden: een zeshoek.","t":"piramide","n":2,"w":{"vijfhoek":"Je haalde er een af, maar het grondvlak is geen driehoek en zit dus niet bij de zes.","driehoek":"De zijvlakken zijn driehoeken, maar het grondvlak heeft evenveel zijden als er zijvlakken zijn.","zevenhoek":"Je telde er een bij; dat doe je voor het aantal vlakken, niet voor het aantal zijden."}},
{"v":"Hoeveel driehoeken heeft de bouwplaat van een piramide met een vijfhoek als grondvlak?","o":["5","6","10","4"],"g":0,"u":"Aan elke zijde van de vijfhoek zit één driehoek. Een vijfhoek heeft 5 zijden, dus 5 driehoeken.","t":"piramide","n":1,"w":{"4":"Vier driehoeken hoort bij een vierkant als grondvlak.","6":"Je telde het grondvlak mee, maar dat is een vijfhoek en geen driehoek.","10":"Je telde de ribben van de piramide (2 × 5) in plaats van de driehoeken."}},
{"v":"De uitslag van een piramide bestaat uit precies vier driehoeken en geen ander vlak. Welke vorm heeft het grondvlak?","o":["een vierkant","een driehoek","een vijfhoek","een rechthoek"],"g":1,"u":"Er zit geen andere vorm bij, dus het grondvlak is zelf een driehoek. De andere drie driehoeken zijn de zijvlakken: 1 + 3 = 4.","t":"piramide","n":3,"w":{"een vierkant":"Bij een vierkant grondvlak zit er naast de vier driehoeken ook een vierkant in de uitslag.","een vijfhoek":"Een vijfhoek geeft vijf driehoeken en ook nog de vijfhoek zelf.","een rechthoek":"Dan zou er naast de vier driehoeken ook een rechthoek in de uitslag zitten."}},
{"v":"Een piramide heeft een zeshoek als grondvlak. Uit hoeveel vlakken bestaat de uitslag?","o":["6","12","7","8"],"g":2,"u":"In de uitslag zit elk vlak van de piramide één keer: 1 zeshoek en 6 driehoeken, samen 7 vlakken.","t":"piramide","n":3,"w":{"6":"Je telde alleen de zes driehoeken en vergat het grondvlak.","8":"Acht vlakken heeft een prisma met een zeshoek, want dat heeft twee grondvlakken.","12":"Je telde de ribben (2 × 6) in plaats van de vlakken."}},
{"v":"Een piramide heeft een vierkant grondvlak met zijden van 6 cm en is 9 cm hoog. Welke driehoek zie je recht van voren?","o":["basis 9 cm, hoogte 6 cm","basis 3 cm, hoogte 9 cm","basis 6 cm, hoogte 3 cm","basis 6 cm, hoogte 9 cm"],"g":3,"u":"Van voren zie je de zijde van het grondvlak als basis (6 cm) en de top recht daarboven op de hoogte van de piramide (9 cm).","t":"piramide","n":2,"w":{"basis 9 cm, hoogte 6 cm":"Je verwisselde de zijde van het grondvlak en de hoogte.","basis 3 cm, hoogte 9 cm":"Je nam de halve zijde, maar in het aanzicht zie je de hele zijde van 6 cm.","basis 6 cm, hoogte 3 cm":"Je deelde de hoogte door 3; dat doe je bij de inhoud, niet in een aanzicht."}},
{"v":"Met welke formule reken je de inhoud van een piramide uit? Met grondvlak bedoelen we de oppervlakte van het grondvlak.","o":["1/3 × grondvlak × hoogte","1/2 × grondvlak × hoogte","grondvlak × hoogte","grondvlak + hoogte"],"g":0,"u":"Een piramide is een derde van een prisma met hetzelfde grondvlak en dezelfde hoogte. Dus inhoud = 1/3 × grondvlak × hoogte.","t":"piramide","n":1,"w":{"1/2 × grondvlak × hoogte":"De helft hoort bij de oppervlakte van een driehoek, niet bij de inhoud van een piramide.","grondvlak × hoogte":"Zo reken je een balk of een prisma uit; bij een piramide komt er nog 1/3 voor.","grondvlak + hoogte":"Bij inhoud vermenigvuldig je; optellen van cm² en cm kan niet."}},
{"v":"Het grondvlak van een piramide is 30 cm². De hoogte is 4 cm. Wat is de inhoud?","o":["120 cm³","40 cm³","60 cm³","34 cm³"],"g":1,"u":"Inhoud = 1/3 × grondvlak × hoogte = 1/3 × 30 × 4 = 1/3 × 120 = 40 cm³.","t":"piramide","n":1,"w":{"120 cm³":"Je deed 30 × 4 en vergat de 1/3.","60 cm³":"Je deelde door 2 in plaats van door 3.","34 cm³":"Je telde 30 en 4 bij elkaar op in plaats van te vermenigvuldigen."}},
{"v":"Een balk en een piramide hebben hetzelfde grondvlak en dezelfde hoogte. De balk is 90 cm³. Hoe groot is de piramide?","o":["45 cm³","270 cm³","30 cm³","90 cm³"],"g":2,"u":"Een piramide is een derde van de balk met hetzelfde grondvlak en dezelfde hoogte: 90 : 3 = 30 cm³.","t":"piramide","n":1,"w":{"45 cm³":"Je nam de helft, maar een piramide is een derde van de balk.","270 cm³":"Je deed keer 3 in plaats van gedeeld door 3; de piramide is juist kleiner.","90 cm³":"De piramide loopt spits toe en is dus kleiner dan de balk."}},
{"v":"Een piramide heeft een vierkant grondvlak met zijden van 3 cm. De hoogte is 8 cm. Wat is de inhoud?","o":["72 cm³","32 cm³","36 cm³","24 cm³"],"g":3,"u":"Het grondvlak is 3 × 3 = 9 cm². Inhoud = 1/3 × 9 × 8 = 1/3 × 72 = 24 cm³.","t":"piramide","n":2,"w":{"72 cm³":"Je deed 9 × 8 en vergat de 1/3.","32 cm³":"Je nam de omtrek van het grondvlak (12) in plaats van de oppervlakte (9).","36 cm³":"Je deelde door 2 in plaats van door 3."}},
{"v":"Een piramide heeft een rechthoek van 5 bij 6 cm als grondvlak en is 7 cm hoog. Wat is de inhoud?","o":["70 cm³","210 cm³","105 cm³","18 cm³"],"g":0,"u":"Het grondvlak is 5 × 6 = 30 cm². Inhoud = 1/3 × 30 × 7 = 1/3 × 210 = 70 cm³.","t":"piramide","n":2,"w":{"210 cm³":"Je deed 5 × 6 × 7 en vergat de 1/3; zo reken je een balk uit.","105 cm³":"Je deelde door 2 in plaats van door 3.","18 cm³":"Je telde de drie maten bij elkaar op in plaats van te vermenigvuldigen."}},
{"v":"Een tent in de vorm van een piramide heeft een vierkante bodem van 3 bij 3 m en is 2 m hoog. Hoeveel lucht zit erin?","o":["18 m³","6 m³","9 m³","8 m³"],"g":1,"u":"De bodem is 3 × 3 = 9 m². Inhoud = 1/3 × 9 × 2 = 1/3 × 18 = 6 m³.","t":"piramide","n":2,"w":{"18 m³":"Je deed 9 × 2 en vergat de 1/3.","9 m³":"Je deelde door 2 in plaats van door 3.","8 m³":"Je nam de omtrek van de bodem (12) in plaats van de oppervlakte (9)."}},
{"v":"Een piramide heeft als grondvlak een driehoek met basis 6 cm en hoogte 5 cm. De piramide is 8 cm hoog. Wat is de inhoud?","o":["80 cm³","120 cm³","40 cm³","240 cm³"],"g":2,"u":"Het grondvlak is 6 × 5 : 2 = 15 cm². Inhoud = 1/3 × 15 × 8 = 1/3 × 120 = 40 cm³.","t":"piramide","n":3,"w":{"80 cm³":"Je vergat bij de driehoek door 2 te delen en rekende met een grondvlak van 30 cm².","120 cm³":"Je deed 15 × 8 en vergat de 1/3.","240 cm³":"Je deed 6 × 5 × 8: zowel het delen door 2 als de 1/3 ontbreekt."}},
{"v":"Een piramide heeft een inhoud van 50 cm³ en een grondvlak van 25 cm². Hoe hoog is de piramide?","o":["2 cm","4 cm","75 cm","6 cm"],"g":3,"u":"Grondvlak × hoogte is 3 keer de inhoud: 3 × 50 = 150. De hoogte is 150 : 25 = 6 cm. Controle: 1/3 × 25 × 6 = 50.","t":"piramide","n":3,"w":{"2 cm":"Je deed 50 : 25 en vergat eerst met 3 te vermenigvuldigen.","4 cm":"Je rekende met keer 2 in plaats van keer 3, alsof de formule met een half begint.","75 cm":"Je telde inhoud en grondvlak bij elkaar op."}},
{"v":"Een piramide van 9 cm hoog heeft een inhoud van 48 cm³. Hoe groot is het grondvlak?","o":["16 cm²","5,3 cm²","432 cm²","144 cm²"],"g":0,"u":"Grondvlak × hoogte is 3 keer de inhoud: 3 × 48 = 144. Het grondvlak is 144 : 9 = 16 cm². Controle: 1/3 × 16 × 9 = 48.","t":"piramide","n":3,"w":{"5,3 cm²":"Je deed 48 : 9 en vergat eerst met 3 te vermenigvuldigen.","432 cm²":"Je deed 48 × 9 in plaats van terug te rekenen.","144 cm²":"Je deed wel 3 × 48, maar vergat daarna door de hoogte te delen."}},
{"v":"Een piramide met een vierkant grondvlak heeft een inhoud van 100 cm³ en is 12 cm hoog. Hoe lang is een zijde van het grondvlak?","o":["25 cm","5 cm","6,25 cm","8,3 cm"],"g":1,"u":"3 × 100 = 300 en 300 : 12 = 25, dus het grondvlak is 25 cm². De zijde is de wortel van 25: 5 cm.","t":"piramide","n":4,"w":{"25 cm":"Dat is de oppervlakte van het grondvlak; je moet nog de wortel nemen voor de zijde.","6,25 cm":"Je deelde het grondvlak door 4, maar dat doe je bij een omtrek, niet bij een oppervlakte.","8,3 cm":"Je deed 100 : 12 en vergat de keer 3 en de wortel."}},
{"v":"Je maakt bij een piramide de hoogte twee keer zo groot en ook alle zijden van het vierkante grondvlak. Hoeveel keer zo groot wordt de inhoud?","o":["2 keer","4 keer","8 keer","6 keer"],"g":2,"u":"Het grondvlak wordt 2 × 2 = 4 keer zo groot en de hoogte 2 keer. Samen: 4 × 2 = 8 keer zo groot.","t":"piramide","n":4,"w":{"2 keer":"Je keek alleen naar de hoogte; het grondvlak groeit ook mee.","4 keer":"Je keek alleen naar het grondvlak en vergat dat de hoogte ook verdubbelt.","6 keer":"Je telde drie keer 2 bij elkaar op, maar de vergrotingen moet je vermenigvuldigen."}},
{"v":"Wat tel je bij elkaar op om de totale oppervlakte van een piramide te krijgen?","o":["alle ribben bij elkaar","alleen de driehoekige zijvlakken","het grondvlak keer de hoogte","het grondvlak en alle zijvlakken"],"g":3,"u":"De totale oppervlakte is alles wat je zou moeten verven: het grondvlak en alle driehoekige zijvlakken samen.","t":"piramide","n":1,"w":{"alle ribben bij elkaar":"Ribben zijn lijnen; als je die optelt krijg je een lengte en geen oppervlakte.","alleen de driehoekige zijvlakken":"Je vergat het grondvlak; dat hoort ook bij de buitenkant.","het grondvlak keer de hoogte":"Dat is de inhoud van een prisma, geen oppervlakte."}},
{"v":"Een piramide heeft een vierkant grondvlak van 4 bij 4 cm. Elk zijvlak is een driehoek met hoogte 5 cm. Wat is de oppervlakte van één zijvlak?","o":["10 cm²","20 cm²","9 cm²","40 cm²"],"g":0,"u":"Een zijvlak is een driehoek met basis 4 cm en hoogte 5 cm: 4 × 5 : 2 = 10 cm².","t":"piramide","n":2,"w":{"20 cm²":"Je deed 4 × 5 en vergat bij de driehoek door 2 te delen.","9 cm²":"Je telde basis en hoogte bij elkaar op in plaats van te vermenigvuldigen.","40 cm²":"Dat zijn alle vier de zijvlakken samen; er wordt naar één zijvlak gevraagd."}},
{"v":"Een piramide heeft een vierkant grondvlak van 6 bij 6 cm. De vier zijvlakken zijn elk 15 cm². Wat is de totale oppervlakte?","o":["60 cm²","96 cm²","51 cm²","84 cm²"],"g":1,"u":"Het grondvlak is 6 × 6 = 36 cm². De zijvlakken zijn samen 4 × 15 = 60 cm². Totaal: 36 + 60 = 96 cm².","t":"piramide","n":2,"w":{"60 cm²":"Je telde alleen de vier zijvlakken en vergat het grondvlak.","51 cm²":"Je telde bij het grondvlak maar één zijvlak op in plaats van vier.","84 cm²":"Je nam de omtrek van het grondvlak (24) in plaats van de oppervlakte (36)."}},
{"v":"Een piramide heeft een vierkant grondvlak met zijden van 10 cm. De hoogte van elk zijvlak is 8 cm. Wat is de totale oppervlakte?","o":["160 cm²","420 cm²","260 cm²","140 cm²"],"g":2,"u":"Grondvlak: 10 × 10 = 100 cm². Eén zijvlak: 10 × 8 : 2 = 40 cm², vier samen 160 cm². Totaal: 100 + 160 = 260 cm².","t":"piramide","n":3,"w":{"160 cm²":"Je telde alleen de vier zijvlakken en vergat het grondvlak.","420 cm²":"Je vergat bij de driehoeken door 2 te delen en rekende met 80 cm² per zijvlak.","140 cm²":"Je telde bij het grondvlak maar één zijvlak op in plaats van vier."}},
{"v":"Een piramide heeft een vierkant grondvlak met zijden van 6 cm en is 4 cm hoog. Hoe lang is de schuine hoogte van een zijvlak?","o":["7 cm","7,2 cm","10 cm","5 cm"],"g":3,"u":"De hoogte (4 cm) en de halve zijde (3 cm) zijn de rechthoekszijden. Pythagoras: 3² + 4² = 9 + 16 = 25, en de wortel van 25 is 5 cm.","t":"piramide","n":3,"w":{"7 cm":"Je telde 3 en 4 op; bij Pythagoras tel je de kwadraten op en neem je daarna de wortel.","7,2 cm":"Je rekende met de hele zijde van 6 cm in plaats van de halve zijde van 3 cm.","10 cm":"Je telde de zijde en de hoogte bij elkaar op in plaats van Pythagoras te gebruiken."}},
{"v":"Een piramide heeft een vierkant grondvlak met zijden van 12 cm en is 8 cm hoog. Hoe hoog is elk driehoekig zijvlak?","o":["10 cm","14 cm","14,4 cm","20 cm"],"g":0,"u":"De hoogte (8 cm) en de halve zijde (6 cm) zijn de rechthoekszijden. Pythagoras: 6² + 8² = 36 + 64 = 100, en de wortel van 100 is 10 cm.","t":"piramide","n":3,"w":{"14 cm":"Je telde 6 en 8 op; bij Pythagoras tel je de kwadraten op en neem je daarna de wortel.","14,4 cm":"Je rekende met de hele zijde van 12 cm in plaats van de halve zijde van 6 cm.","20 cm":"Je telde de zijde en de hoogte bij elkaar op in plaats van Pythagoras te gebruiken."}},
{"v":"De schuine hoogte van een zijvlak van een piramide is 5 cm. Het vierkante grondvlak heeft zijden van 8 cm. Hoe hoog is de piramide?","o":["6,4 cm","3 cm","1 cm","9,4 cm"],"g":1,"u":"De schuine hoogte is de langste zijde, de halve zijde is 4 cm. Pythagoras: 5² min 4² is 25 min 16 = 9, en de wortel van 9 is 3 cm.","t":"piramide","n":3,"w":{"6,4 cm":"Je telde de kwadraten op, maar de schuine hoogte is de langste zijde: je moet aftrekken.","1 cm":"Je deed 5 min 4 zonder te kwadrateren en de wortel te nemen.","9,4 cm":"Je rekende met de hele zijde van 8 cm en telde de kwadraten op in plaats van af te trekken."}},
{"v":"Een piramide heeft een vierkant grondvlak van 10 bij 10 cm en is 12 cm hoog. Wat is de totale oppervlakte?","o":["260 cm²","340 cm²","360 cm²","620 cm²"],"g":2,"u":"Schuine hoogte: 5² + 12² = 169, dus 13 cm. Eén zijvlak is 10 × 13 : 2 = 65 cm², vier samen 260 cm². Met het grondvlak: 260 + 100 = 360 cm².","t":"piramide","n":4,"w":{"260 cm²":"Je telde alleen de vier zijvlakken en vergat het grondvlak van 100 cm².","340 cm²":"Je gebruikte de hoogte van de piramide (12 cm) als hoogte van het zijvlak; die is 13 cm.","620 cm²":"Je vergat bij de driehoeken door 2 te delen en rekende met 130 cm² per zijvlak."}},
{"v":"Bij een piramide met een vierkant grondvlak is de halve diagonaal van het grondvlak 5 cm. De hoogte is 12 cm. Hoe lang is een opstaande ribbe?","o":["17 cm","10,9 cm","15,6 cm","13 cm"],"g":3,"u":"De hoogte en de halve diagonaal zijn de rechthoekszijden, de ribbe is de langste zijde. Pythagoras: 5² + 12² = 25 + 144 = 169, de wortel is 13 cm.","t":"piramide","n":4,"w":{"17 cm":"Je telde 5 en 12 op; bij Pythagoras tel je de kwadraten op en neem je daarna de wortel.","10,9 cm":"Je trok de kwadraten van elkaar af, maar de ribbe is de langste zijde: je moet optellen.","15,6 cm":"Je rekende met de hele diagonaal van 10 cm in plaats van de halve van 5 cm."}}
];
